package operators;

public class AssignmentOp {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a = 10;
		
		System.out.println(a = 10);
		System.out.println(a += 5);
		System.out.println(a -= 5);
		System.out.println(a /= 2);
		System.out.println(a %= 5);
		System.out.println(a *= 5);
	}

}
